#include "ProjectSearchDialog.h"
#include <QtWidgets>
#include <QDirIterator>
ProjectSearchDialog::ProjectSearchDialog(const QString&root,QWidget*p):QDialog(p),m_root(root){setWindowTitle("Find in Project");resize(850,600);auto*l=new QVBoxLayout(this);auto*row=new QHBoxLayout;m_query=new QLineEdit;m_query->setPlaceholderText("Text or symbol...");m_case=new QCheckBox("Case sensitive");auto*b=new QPushButton("Find");row->addWidget(m_query,1);row->addWidget(m_case);row->addWidget(b);l->addLayout(row);m_results=new QTreeWidget;m_results->setHeaderLabels({"File","Line","Preview"});m_results->setRootIsDecorated(false);l->addWidget(m_results,1);connect(b,&QPushButton::clicked,this,[this]{search();});connect(m_query,&QLineEdit::returnPressed,this,[this]{search();});connect(m_results,&QTreeWidget::itemDoubleClicked,this,[this](QTreeWidgetItem*i,int){if(!i||!m_open)return;m_open(i->data(0,Qt::UserRole).toString(),i->data(1,Qt::UserRole).toInt());});}
void ProjectSearchDialog::search(){m_results->clear();QString q=m_query->text();if(q.isEmpty())return;Qt::CaseSensitivity cs=m_case->isChecked()?Qt::CaseSensitive:Qt::CaseInsensitive;QDirIterator it(m_root,QStringList{"*.c","*.cc","*.cpp","*.cxx","*.h","*.hpp","*.vsm","*.ps2scene","*.json","Makefile"},QDir::Files,QDirIterator::Subdirectories);int hits=0;while(it.hasNext()&&hits<2000){QString path=it.next();if(path.contains("/build/")||path.contains("\\build\\"))continue;QFile f(path);if(!f.open(QIODevice::ReadOnly|QIODevice::Text))continue;int ln=0;while(!f.atEnd()&&hits<2000){QString line=QString::fromUtf8(f.readLine());++ln;if(!line.contains(q,cs))continue;auto*i=new QTreeWidgetItem({QDir(m_root).relativeFilePath(path),QString::number(ln),line.trimmed().left(160)});i->setData(0,Qt::UserRole,path);i->setData(1,Qt::UserRole,ln);m_results->addTopLevelItem(i);++hits;}}setWindowTitle(QString("Find in Project — %1 result(s)").arg(hits));}
